def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "dial_friend": And([
            Not(self.friend_available()),
            self.robot_has_contact(self.friend),
            self.robot_has_dialing_ability,
            Not(self.voicemail_available())
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
